for state in ['initial','lower_contact','deeper','lift_deep','lower_side']:
 m=json.load(open(f'/app/output/{state}/meta.json')); print('\n',state)
 for cam,roi in [('top',(125,65,205,130)),('front',(125,65,200,145)),('oblique',(130,75,220,165))]:
  a=np.array(Image.open(f'/app/output/{state}/last/{cam}.jpg')); d=np.load(f'/app/output/{state}/depth_{cam}.npy')[-1].astype(float)
  x0,y0,x1,y1=roi; yy,xx=np.mgrid[y0:y1,x0:x1]; col=a[y0:y1,x0:x1].astype(float); sat=col.max(2)-col.min(2); val=col.mean(2); dd=d[y0:y1,x0:x1]
  for th in [1.0,1.05]:
   mask=(dd<th)&(sat<90)&(val>100)
   if mask.sum()>0:
    K=np.array(m['cameras'][cam]['intrinsic_cv']);T=np.array(m['cameras'][cam]['cam2world_gl']);R=T[:3,:3]@np.diag([1,-1,-1]);
    u=xx[mask];v=yy[mask];dep=dd[mask]
    pc=np.stack([(u-K[0,2])/K[0,0]*dep,(v-K[1,2])/K[1,1]*dep,dep],1); pw=pc@R.T+T[:3,3]
    print(cam,th,'n',mask.sum(),'xyz',np.round(pw.mean(0),3),'bbox', (u.min(),v.min(),u.max(),v.max()))
